public class Main {
  public static void main(String[] args) throws Exception {
    FastScanner in = new FastScanner(System.in);
    int n = in.nextInt(), limit = in.nextInt();
    int[] latency = new int[n];
    for (int i = 0; i < n; i++)
      latency[i] = in.nextInt();
    System.out.println(new Solution().longestStableWindow(latency, limit));
  }
  static final class FastScanner {
    private final InputStream in;
    private final byte[] b = new byte[1 << 16];
    private int p, l;
    FastScanner(InputStream in) { this.in = in; }
    int read() throws IOException {
      if (p >= l) {
        l = in.read(b);
        p = 0;
        if (l < 0)
          return -1;
      }
      return b[p++];
    }
    int nextInt() throws IOException {
      int c, s = 1, v = 0;
      do
        c = read();
      while (c <= 32);
      if (c == '-') {
        s = -1;
        c = read();
      }
      while (c > 32) {
        v = v * 10 + c - '0';
        c = read();
      }
      return v * s;
    }
  }
}

